import {expect, test} from '@playwright/test';
import {apiURL, bearer, credentials, login} from '../../src/support/api';

/** IDs generated by `npm run qa:discover`. These tests never create or delete resources. */
const owner = credentials('owner');
const uuid=/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

test('@smoke discovered room contents are readable and paginated',async ({request}) => {
  const id=process.env.LHCI_ROOM_ID;
  test.skip(!owner || !id,'Run qa:discover and set OWNER credentials first');
  expect(id).toMatch(uuid);
  const token=await login(request,owner!);
  const room=await request.get(`${apiURL}/data-rooms/${id}`,{headers:bearer(token)});
  expect(room.status()).toBe(200);
  const response=await request.get(`${apiURL}/data-rooms/${id}/contents?limit=3`,{headers:bearer(token)});
  expect(response.status()).toBe(200);
  const page=await response.json() as {items:unknown[];nextCursor:string|null};
  expect(Array.isArray(page.items)).toBe(true);
  expect(page.items.length).toBeLessThanOrEqual(3);
  expect(page).toHaveProperty('nextCursor');
});

test('@smoke discovered folder returns a valid empty or populated list',async ({request}) => {
  const id=process.env.LHCI_FOLDER_ID;
  test.skip(!owner || !id,'No test folder discovered');
  expect(id).toMatch(uuid);
  const token=await login(request,owner!);
  const response=await request.get(`${apiURL}/folders/${id}/contents?limit=10`,{headers:bearer(token)});
  expect(response.status()).toBe(200);
  const page=await response.json() as {items:unknown[];nextCursor:string|null};
  expect(Array.isArray(page.items)).toBe(true); // Empty folder is a valid state.
});

test('@smoke discovered PDF is readable and has PDF metadata',async ({request}) => {
  const id=process.env.LHCI_FILE_ID;
  test.skip(!owner || !id,'Overview.pdf not discovered, or ambiguous');
  expect(id).toMatch(uuid);
  const token=await login(request,owner!);
  const response=await request.get(`${apiURL}/files/${id}`,{headers:bearer(token)});
  expect(response.status()).toBe(200);
  const file=await response.json() as {id:string;name:string;mimeType:string;size:number};
  expect(file.id).toBe(id);
  expect(file.mimeType).toBe('application/pdf');
  expect(file.size).toBeGreaterThan(0);
});
